import math
    import random
    import time

    LANGUAGE_WRAPPER = 'In an {n}x{n} grid of cells, where {n} is even, the integers 1, 2, ..., {n_sq} are placed in the cells, one per cell. Consider the following two fixed perfect matchings of grid-adjacent pairs: (i) the horizontal matching that, for each row, pairs columns (1,2), (3,4), ..., ({n_minus_1},{n}); and (ii) the vertical matching that, for each column, pairs rows (1,2), (3,4), ..., ({n_minus_1},{n}). Let S be the largest real number such that there exists a placement of the integers with the property that for every matched pair in either matching, the sum of the two integers in that pair is at least S. Determine the maximum possible value of S as a function of {n}.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Choose an even n in a nontrivial range to ensure problem substance
# Keep n fairly large to avoid trivial small cases and ensure consistent difficulty
lo, hi = 6, 60
# ensure even bounds
if lo % 2 == 1:
    lo += 1
if hi % 2 == 1:
    hi -= 1
# random even n
# retry just in case
for _ in range(100):
    n = rng.randrange(lo, hi + 1, 2)
    if n % 2 == 0 and n >= 6:
        n_sq = n * n
        return {
            'n': n,
            'n_sq': n_sq,
            'n_minus_1': n - 1
        }
# Fallback deterministic choice if RNG somehow fails
n = 10
return {'n': n, 'n_sq': n*n, 'n_minus_1': n-1}

    def verifier(assign):
# Validate input
if 'n' not in assign:
    # Missing required parameter
    return (False, None)
n = assign['n']
# Domain constraints
if not isinstance(n, int):
    return (False, None)
if n < 2 or n % 2 != 0:
    # Problem statement requires even n >= 2
    return (False, None)
# Compute the answer: S* = n^2 (for even n)
# Proof sketch (correctness):
# Upper bound: Each cell participates in exactly two pairs (one horizontal, one vertical).
# The sum of all pair-sums across the two matchings equals 2 * sum_{v} value(v) = n^2 (n^2 + 1).
# If every pair-sum were >= n^2 + 1, then the total would be >= n^2 * (n^2 + 1), forcing equality.
# Equality would require both matchings to consist entirely of complementary pairs summing to n^2 + 1,
# which is impossible since each value has a unique complement but belongs to two distinct pairs.
# Hence at least one pair has sum <= n^2, implying S <= n^2.
# Lower bound (construction): Partition the grid into 2x2 blocks aligned with the matchings.
# Partition the set {1, ..., n^2/2} into consecutive pairs (1,2), (3,4), ..., and for each pair (x,y)
# place the quadruple {x, y, n^2+1-x, n^2+1-y} in a 2x2 block as
# [ x, n^2+1-y; n^2+1-x, y ]. Then vertical matched sums are both n^2+1, and horizontal matched sums
# are both n^2+1 - |x-y| >= n^2. Thus S >= n^2, so S* = n^2.
answer = n * n
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

